function Summary = run_ip_poe_prediction_reference_comparison( ...
    do_run,m_value,dac_rounds,simulation_end_time)
%RUN_IP_POE_PREDICTION_REFERENCE_COMPARISON Compare PoE prediction paths.
%
% All prediction methods are evaluated on the state trajectory generated by
% IP-DAC.  Direct PoE and IP-CEN are shadow predictors and do not alter the
% controller, local GP updates, inducing points, or physical trajectory.

if nargin < 1 || isempty(do_run), do_run = true; end
if nargin < 2 || isempty(m_value), m_value = 600; end
if nargin < 3 || isempty(dac_rounds), dac_rounds = 10; end
if nargin < 4 || isempty(simulation_end_time), simulation_end_time = 10; end

repo_root = fileparts(fileparts(mfilename('fullpath')));
addpath(genpath(repo_root));
result_folder = fullfile(repo_root,'result','ip_prediction_reference_comparison');
if ~isfolder(result_folder), mkdir(result_folder); end

env_names = {'CONTROL_SIM_END_TIME','CONTROL_IP_NUM_INDUCING_POINTS', ...
    'CONTROL_DAC_STEPS_PER_PHYSICAL_STEP','CONTROL_IP_PROJECTION_DIAGNOSTICS'};
old_values = cellfun(@getenv,env_names,'UniformOutput',false);
cleanup_env = onCleanup(@() restore_environment(env_names,old_values)); %#ok<NASGU>
setenv(env_names{1},num2str(simulation_end_time,'%.15g'));
setenv(env_names{2},num2str(m_value));
setenv(env_names{3},num2str(dac_rounds));
setenv(env_names{4},'1');

result_file = fullfile(result_folder, ...
    sprintf('poe_M%d_R%d.mat',m_value,dac_rounds));
if do_run
    run_simulation_inducing_point('poe',result_folder, ...
        sprintf('poe_M%d_R%d',m_value,dac_rounds),false,[],[],[],42);
end
data = load(result_file);

t = data.t_set(:);
valid = isfinite(data.direct_prediction_error_norm_vector(:)) & ...
    isfinite(data.ip_cen_prediction_error_norm_vector(:)) & ...
    isfinite(data.prediction_error_norm_vector(:));
t_plot = t(valid);
error_direct = data.direct_prediction_error_norm_vector(valid).';
error_cen = data.ip_cen_prediction_error_norm_vector(valid).';
error_dac = data.prediction_error_norm_vector(valid).';

Method = {'Direct PoE';'IP-CEN';'IP-DAC'};
MeanPredictionError = [mean(error_direct);mean(error_cen);mean(error_dac)];
FinalPredictionError = [error_direct(end);error_cen(end);error_dac(end)];
MaximumPredictionError = [max(error_direct);max(error_cen);max(error_dac)];
Summary = table(Method,MeanPredictionError,FinalPredictionError,MaximumPredictionError);
writetable(Summary,fullfile(result_folder, ...
    sprintf('summary_M%d_R%d.csv',m_value,dac_rounds)));
save(fullfile(result_folder,sprintf('summary_M%d_R%d.mat',m_value,dac_rounds)), ...
    'Summary','m_value','dac_rounds','simulation_end_time');

%% Prediction error along the common IP-DAC trajectory
error_fig = figure('Color','w','Position',[100 100 1050 560]);
ax = axes(error_fig); hold(ax,'on');
plot(ax,t_plot,error_direct,'LineWidth',1.8,'DisplayName','Direct PoE');
plot(ax,t_plot,error_cen,'LineWidth',1.8,'DisplayName','IP-CEN');
plot(ax,t_plot,error_dac,'LineWidth',1.8,'DisplayName','IP-DAC');
xlabel(ax,'Time (s)');
ylabel(ax,'Prediction error norm');
title(ax,sprintf('PoE prediction paths on the same trajectory (M=%d, DAC rounds=%d)', ...
    m_value,dac_rounds));
legend(ax,'Location','best'); grid(ax,'on'); box(ax,'on');
xlim(ax,[t_plot(1),t_plot(end)]);
exportgraphics(error_fig,fullfile(result_folder, ...
    sprintf('prediction_error_M%d_R%d.png',m_value,dac_rounds)),'Resolution',220);
savefig(error_fig,fullfile(result_folder, ...
    sprintf('prediction_error_M%d_R%d.fig',m_value,dac_rounds)));

%% True dynamics and the three predictors; six agents in every panel
agent_colors = lines(size(data.f_true_all_set,2));
for output_i = 1:size(data.f_true_all_set,1)
    dynamics_fig = figure('Color','w','Position',[120 80 1250 720]);
    layout = tiledlayout(dynamics_fig,2,2,'TileSpacing','compact','Padding','compact');
    methods = {data.f_true_all_set,'True dynamics'; ...
        data.f_direct_all_set,'Direct PoE'; ...
        data.f_ip_cen_all_set,'IP-CEN'; ...
        data.f_hat_all_set,'IP-DAC'};
    axes_set = gobjects(4,1);
    for method_i = 1:4
        axes_set(method_i) = nexttile(layout); hold(axes_set(method_i),'on');
        values = methods{method_i,1};
        for agent_i = 1:size(values,2)
            y = squeeze(values(output_i,agent_i,valid));
            plot(axes_set(method_i),t_plot,y,'Color',agent_colors(agent_i,:), ...
                'LineWidth',1.15,'DisplayName',sprintf('Agent %d',agent_i));
        end
        title(axes_set(method_i),methods{method_i,2});
        ylabel(axes_set(method_i),sprintf('f_%d',output_i));
        xlim(axes_set(method_i),[t_plot(1),t_plot(end)]);
        grid(axes_set(method_i),'on'); box(axes_set(method_i),'on');
    end
    linkaxes(axes_set,'xy');
    xlabel(layout,'Time (s)');
    title(layout,sprintf('Unknown dynamics output %d on the same IP-DAC trajectory',output_i));
    legend(axes_set(2),'Location','best');
    exportgraphics(dynamics_fig,fullfile(result_folder, ...
        sprintf('dynamics_output%d_M%d_R%d.png',output_i,m_value,dac_rounds)), ...
        'Resolution',220);
    savefig(dynamics_fig,fullfile(result_folder, ...
        sprintf('dynamics_output%d_M%d_R%d.fig',output_i,m_value,dac_rounds)));
end

disp(Summary);
end

function restore_environment(names,values)
for idx = 1:numel(names), setenv(names{idx},values{idx}); end
end
